# NAND2Tetris Projects

These are the official project files for the NAND2Tetris Course.

For downloads of the Java simulator, [click here](https://www.nand2tetris.org/software).

For the web ide, [click here](https://nand2tetris.github.io/web-ide/).---
.DS_Store
node_modules/
*.zip
---WORKFLOW---
name: Release Packer

on:
  release:
    types: [published]

jobs:
  build:
    runs-on: ubuntu-latest

    permissions:
      contents: write

    steps:
      - name: Checkout code
        uses: actions/checkout@v4

      - name: Zip the project
        run: |
          zip -r projects.zip projects README.md

      - name: Upload Release Asset
        uses: softprops/action-gh-release@v1
        with:
          files: projects.zip
---
// File name: projects/01/Mux.hdl
CHIP Mux {
    IN a, b, sel;
    OUT out;
    PARTS:
    // TODO: implement
}
---
// File name: projects/01/Xor.hdl
CHIP Xor {
    IN a, b;
    OUT out;
    PARTS:
    // TODO: implement
}
--- demo Xor
// This file is part of www.nand2tetris.org
// and the book "The Elements of Computing Systems"
// by Nisan and Schocken, MIT Press.
// File name: projects/demo/Xor.hdl

/**
 *  Exclusive-or gate: true if either a is true and b is false, or
 *  a is false and b is true; false otherwise.
 *  QUESTION: how can the simulator execute this program properly without
 *  HDL implementations of the underlying Not, And, and Or chip-parts?
 *  Answer: since the demo folder contains no Not.hdl, And.hdl and Or.hdl
 *  files, the simulator reverts to using their built-in implementations.
 */

CHIP Xor {
    IN a, b;
    OUT out;

    PARTS:
    Not (in=a, out=nota);
    Not (in=b, out=notb);
    And (a=a, b=notb, out=x);
    And (a=nota, b=b, out=y);
    Or (a=x, b=y, out=out);
}--- demo tst
// This file is part of www.nand2tetris.org
// and the book "The Elements of Computing Systems"
// by Nisan and Schocken, MIT Press.
// File name: projects/01/Xor.tst

load Xor.hdl,
output-file Xor.out,
compare-to Xor.cmp,
output-list a%B3.1.3 b%B3.1.3 out%B3.1.3;

set a 0,
set b 0,
eval,
output;

set a 0,
set b 1,
eval,
output;

set a 1,
set b 0,
eval,
output;

set a 1,
set b 1,
eval,
output;

